const outputs=$json.data?.outputs||$json.outputs||{};
let decision={};
if(outputs.analysis_json&&typeof outputs.analysis_json==='object'){decision=outputs.analysis_json;}
else if($json.analysis_json&&typeof $json.analysis_json==='object'){decision=$json.analysis_json;}
else if(Array.isArray(outputs.verdicts)||outputs.action||outputs.dashboardSummary){decision=outputs;}
else if(Array.isArray($json.verdicts)||$json.action){decision=$json;}
else{
const rawText=String(outputs.text||outputs.result||outputs.analysis_json||$json.analysis_json||$json.data?.analysis_json||$json.answer||$json.text||$json.body||$json.data||'');
const chunks=[];for(const line of rawText.split(/\r?\n/)){if(!line.startsWith('data:'))continue;try{const event=JSON.parse(line.slice(5).trim());if(typeof event.answer==='string')chunks.push(event.answer);}catch{}}
const raw=chunks.join('')||rawText;
try{decision=JSON.parse(raw.trim());}catch(e){
const object=text=>{let start=-1,depth=0,q=false,esc=false,last;for(let i=0;i<text.length;i++){const c=text[i];if(q){if(esc)esc=false;else if(c==='\\')esc=true;else if(c==='"')q=false;continue;}if(c==='"'){q=true;continue;}if(c==='{'){if(!depth)start=i;depth++;}else if(c==='}'&&depth&&!--depth){try{last=JSON.parse(text.slice(start,i+1));}catch{}}}return last;};
decision=object(raw)||{};
}
}
console.log('ParseDify: keys='+Object.keys(decision).join(',')+' verdicts='+((decision.verdicts||[]).length));
return [{json:{difyText:JSON.stringify(decision).slice(-20000),decision}}];

const norm=$('Normalize Batch').first().json,parsed=$json,job=norm.job||{},source=job.cases||[];
const text=(v,m,f)=>{const s=typeof v==='string'?v.trim():String(v||'');return s.slice(0,m)||f||'';};
const list=(v,n,m)=>(Array.isArray(v)?v:v?[v]:[]).map(i=>String(i||'').trim()).filter(Boolean).slice(0,n).map(i=>i.slice(0,m));
const missing=$('Parse Dify Missing Response').first();
let verdicts=Array.isArray(parsed.decision?.verdicts)?parsed.decision.verdicts:[];
if(missing&&missing.json){const _mv=Array.isArray(missing.json.decision?.verdicts)?missing.json.decision.verdicts:[];verdicts=verdicts.concat(_mv);}
const sourceSet=new Set(source.map(c=>Number(c.anomalyIndex)));
const matched=new Map();
for(const raw of verdicts){const i=Number(raw?.anomalyIndex);if(sourceSet.has(i)&&!matched.has(i))matched.set(i,raw);}
const results=source.map(c=>{const raw=matched.get(Number(c.anomalyIndex))||{anomalyIndex:c.anomalyIndex,summary:'Dify 未返回该指标判断，需人工核查',evidence:[],limitations:'Dify 响应缺少该指标 verdict',dataSideVerdict:'insufficient_evidence',notificationAction:'send',confidence:'low'};
const idx=Number(c.anomalyIndex);
return{anomalyIndex:idx,analysis:{
summary:text(raw.summary,1200,'Evidence collection finished.'),
evidence:list(raw.evidence,5,600),
possibleCauses:list(raw.possibleCauses,3,600),
verificationSteps:list(raw.verificationSteps,3,600),
recommendedActions:list(raw.recommendedActions,3,600),
confidence:['low','medium','high'].includes(raw.confidence)?raw.confidence:raw.screeningVerdict==='verified_normal'?'high':'low',
limitations:text(raw.limitations,1600,parsed.difyText?.slice(-500)||'Evidence is bounded.'),
dataSideVerdict:['data_issue','business_change','verified_normal','insufficient_evidence'].includes(raw.dataSideVerdict)?raw.dataSideVerdict:raw.screeningVerdict==='verified_normal'?'verified_normal':raw.screeningVerdict==='suspected_issue'?'data_issue':'insufficient_evidence',
notificationAction:['send','downgrade','enrich_only'].includes(raw.notificationAction)?raw.notificationAction:raw.screeningVerdict==='verified_normal'?'enrich_only':'send',
chartVisibility:raw.dataSideVerdict==='verified_normal'||raw.screeningVerdict==='verified_normal'||raw.chartVisibility==='hide_verified_normal'?'hide_verified_normal':'show',
verdictMissing:raw.verdictMissing===true,
verificationReason:text(raw.verificationReason,600)
},evidence:{evidenceChain:[]}}});
console.log('BuildCallback: results='+results.length+' matched='+matched.size+' callbackUrl='+(norm.callbackUrl||''));return[{json:{callbackUrl:norm.callbackUrl||'http://127.0.0.1:8787/api/metabase-anomaly-analysis/batch-callback',runId:job.runId,countryCode:job.countryCode,jobId:norm.jobId,callbackToken:norm.callbackToken,results}}];

const norm=$('Normalize Batch').first().json;
const job=norm.job||{};
const source=Array.isArray(job.cases)?job.cases:[];
const parsed=$json||{};
const verdicts=Array.isArray(parsed.decision?.verdicts)?parsed.decision.verdicts:[];
const sourceSet=new Set(source.map(c=>Number(c.anomalyIndex)));
const matched=new Set();
for(const raw of verdicts){const i=Number(raw?.anomalyIndex);if(sourceSet.has(i))matched.add(i);}
const missing=source.filter(c=>!matched.has(Number(c.anomalyIndex)));
if(missing.length===0){return[];}
return missing.map(c=>({json:{jobId:norm.jobId,job:{stage:job.stage,runId:job.runId,countryCode:job.countryCode,batchId:job.batchId,snapshotId:job.snapshotId,dashboardUuid:job.dashboardUuid,dashboardTitle:job.dashboardTitle,cases:[c]}}}));

